export const EVENT_MCP_TOOL_USAGE = "NEXT_MCP_TOOL_USAGE";
export function eventMcpToolUsage(usages) {
    return usages.map(({ featureName, invocationCount }) => ({
        eventName: EVENT_MCP_TOOL_USAGE,
        fields: {
            toolName: featureName,
            invocationCount,
        },
    }));
}
